    desc,checks=DETAILS.get(n,(acceptance,[acceptance]))
    tasks.append(dict(id=n,title=f'[ЛР4-{n:02d}] {actual_title}',original_title=title,owner=PEOPLE[owner],assignee_login=None,
        week_start=w1,week_end=w2,start_date=str(START+timedelta(days=(w1-1)*7)),end_date=str(START+timedelta(days=w2*7-1)),
        estimated_hours=h,dependencies=[dict(task_id=d,type=kind) for d,kind in deps],status='Todo' if n in TODO else 'In Progress',
        description=desc,acceptance_criteria=checks,evidence=evidence,issue_url=None))

